CREATE TABLE public.shelters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.shelters TO authenticated; GRANT ALL ON public.shelters TO service_role;
ALTER TABLE public.shelters ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.shelter_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shelter_id uuid NOT NULL REFERENCES public.shelters(id), user_id uuid NOT NULL UNIQUE, role text NOT NULL DEFAULT 'staff' CHECK (role IN ('owner','staff')), email text NOT NULL DEFAULT '');
GRANT SELECT ON public.shelter_members TO authenticated; GRANT ALL ON public.shelter_members TO service_role;
ALTER TABLE public.shelter_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.my_shelter_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT shelter_id FROM public.shelter_members WHERE user_id=auth.uid() $$;
CREATE FUNCTION public.is_shelter_owner(_shelter uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.shelter_members WHERE user_id=auth.uid() AND shelter_id=_shelter AND role='owner') $$;
REVOKE ALL ON FUNCTION public.my_shelter_id() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.my_shelter_id() TO authenticated;
REVOKE ALL ON FUNCTION public.is_shelter_owner(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_shelter_owner(uuid) TO authenticated;
CREATE POLICY shelter_member_read ON public.shelters FOR SELECT TO authenticated USING (id=public.my_shelter_id());
CREATE POLICY membership_read ON public.shelter_members FOR SELECT TO authenticated USING (shelter_id=public.my_shelter_id());
CREATE TABLE public.shelter_settings (shelter_id uuid PRIMARY KEY REFERENCES public.shelters(id), capacity integer NOT NULL DEFAULT 40, staff_email text);
GRANT SELECT,UPDATE ON public.shelter_settings TO authenticated; GRANT ALL ON public.shelter_settings TO service_role;
ALTER TABLE public.shelter_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_member_read ON public.shelter_settings FOR SELECT TO authenticated USING (shelter_id=public.my_shelter_id());
CREATE POLICY settings_member_update ON public.shelter_settings FOR UPDATE TO authenticated USING (shelter_id=public.my_shelter_id()) WITH CHECK (shelter_id=public.my_shelter_id());
CREATE TABLE public.shelter_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shelter_id uuid NOT NULL REFERENCES public.shelters(id), email text NOT NULL, token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', used_at timestamptz);
GRANT SELECT,INSERT,DELETE ON public.shelter_invites TO authenticated; GRANT ALL ON public.shelter_invites TO service_role;
ALTER TABLE public.shelter_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_invites ON public.shelter_invites FOR ALL TO authenticated USING (public.is_shelter_owner(shelter_id)) WITH CHECK (public.is_shelter_owner(shelter_id));
ALTER TABLE public.cats ADD COLUMN shelter_id uuid REFERENCES public.shelters(id);
ALTER TABLE public.tasks ADD COLUMN shelter_id uuid REFERENCES public.shelters(id);
ALTER TABLE public.applications ADD COLUMN shelter_id uuid REFERENCES public.shelters(id);
ALTER TABLE public.vet_logs ADD COLUMN shelter_id uuid REFERENCES public.shelters(id);
INSERT INTO public.shelters(id,name,slug) VALUES ('11111111-1111-4111-8111-111111111111','Whisker Haven','whisker-haven');
INSERT INTO public.shelter_members(shelter_id,user_id,role,email) SELECT '11111111-1111-4111-8111-111111111111',r.user_id,CASE WHEN row_number() OVER (ORDER BY u.created_at)=1 THEN 'owner' ELSE 'staff' END,u.email FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.role='staff';
INSERT INTO public.shelter_settings(shelter_id,capacity,staff_email) SELECT '11111111-1111-4111-8111-111111111111',capacity,staff_email FROM public.settings WHERE id=1;
