UPDATE public.tasks SET shelter_id='11111111-1111-4111-8111-111111111111';
UPDATE public.applications SET shelter_id='11111111-1111-4111-8111-111111111111';
UPDATE public.vet_logs SET shelter_id='11111111-1111-4111-8111-111111111111';
ALTER TABLE public.cats ALTER COLUMN shelter_id SET NOT NULL;
ALTER TABLE public.tasks ALTER COLUMN shelter_id SET NOT NULL;
ALTER TABLE public.applications ALTER COLUMN shelter_id SET NOT NULL;
ALTER TABLE public.vet_logs ALTER COLUMN shelter_id SET NOT NULL;
ALTER TABLE public.cats ADD CONSTRAINT cats_shelter_id_unique UNIQUE(id,shelter_id);
ALTER TABLE public.applications ADD CONSTRAINT application_same_shelter FOREIGN KEY(cat_id,shelter_id) REFERENCES public.cats(id,shelter_id);
ALTER TABLE public.vet_logs ADD CONSTRAINT vet_same_shelter FOREIGN KEY(cat_id,shelter_id) REFERENCES public.cats(id,shelter_id);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cats,public.tasks,public.applications,public.vet_logs TO authenticated;
GRANT ALL ON public.cats,public.tasks,public.applications,public.vet_logs TO service_role;
CREATE POLICY member_cats ON public.cats FOR ALL TO authenticated USING(shelter_id=public.my_shelter_id()) WITH CHECK(shelter_id=public.my_shelter_id());
CREATE POLICY member_tasks ON public.tasks FOR ALL TO authenticated USING(shelter_id=public.my_shelter_id()) WITH CHECK(shelter_id=public.my_shelter_id());
CREATE POLICY member_applications ON public.applications FOR ALL TO authenticated USING(shelter_id=public.my_shelter_id()) WITH CHECK(shelter_id=public.my_shelter_id());
CREATE POLICY member_vet_logs ON public.vet_logs FOR ALL TO authenticated USING(shelter_id=public.my_shelter_id()) WITH CHECK(shelter_id=public.my_shelter_id());
CREATE INDEX cats_shelter_idx ON public.cats(shelter_id); CREATE INDEX tasks_shelter_idx ON public.tasks(shelter_id); CREATE INDEX applications_shelter_idx ON public.applications(shelter_id); CREATE INDEX vet_logs_shelter_idx ON public.vet_logs(shelter_id);
CREATE FUNCTION public.create_my_shelter(_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF EXISTS(SELECT 1 FROM public.shelter_members WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Already a shelter member'; END IF; IF length(trim(_name))<1 OR length(_name)>100 THEN RAISE EXCEPTION 'Invalid shelter name'; END IF; INSERT INTO public.shelters(name,slug) VALUES(trim(_name),'rescue-'||gen_random_uuid()::text) RETURNING id INTO sid; INSERT INTO public.shelter_members(shelter_id,user_id,role,email) SELECT sid,id,'owner',email FROM auth.users WHERE id=auth.uid(); INSERT INTO public.shelter_settings(shelter_id,staff_email) SELECT sid,email FROM auth.users WHERE id=auth.uid(); RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.create_my_shelter(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_my_shelter(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.grant_first_staff() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; inv public.shelter_invites; shelter_name text; BEGIN IF nullif(NEW.raw_user_meta_data->>'invite_token','') IS NOT NULL THEN SELECT * INTO inv FROM public.shelter_invites WHERE token::text=NEW.raw_user_meta_data->>'invite_token' AND lower(email)=lower(NEW.email) AND used_at IS NULL AND expires_at>now() FOR UPDATE; IF inv.id IS NULL THEN RAISE EXCEPTION 'Invitation is invalid or expired'; END IF; INSERT INTO public.shelter_members(shelter_id,user_id,role,email) VALUES(inv.shelter_id,NEW.id,'staff',NEW.email); UPDATE public.shelter_invites SET used_at=now() WHERE id=inv.id; ELSE shelter_name:=trim(coalesce(NEW.raw_user_meta_data->>'shelter_name','My rescue')); IF length(shelter_name)<1 OR length(shelter_name)>100 THEN RAISE EXCEPTION 'Invalid shelter name'; END IF; INSERT INTO public.shelters(name,slug) VALUES(shelter_name,'rescue-'||gen_random_uuid()::text) RETURNING id INTO sid; INSERT INTO public.shelter_members(shelter_id,user_id,role,email) VALUES(sid,NEW.id,'owner',NEW.email); INSERT INTO public.shelter_settings(shelter_id,staff_email) VALUES(sid,NEW.email); END IF; RETURN NEW; END $$;
CREATE FUNCTION public.remove_shelter_staff(_member uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.shelter_members WHERE id=_member AND role='staff' AND public.is_shelter_owner(shelter_id); IF NOT FOUND THEN RAISE EXCEPTION 'Not allowed'; END IF; END $$;
REVOKE ALL ON FUNCTION public.remove_shelter_staff(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.remove_shelter_staff(uuid) TO authenticated;
CREATE FUNCTION public.public_adoption_page(_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('shelter',jsonb_build_object('id',s.id,'name',s.name,'slug',s.slug),'cats',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'photo_url',c.photo_url,'breed',c.breed,'color',c.color,'age_years',c.age_years,'sex',c.sex,'temperament',c.temperament,'bio',c.bio) ORDER BY c.created_at DESC) FROM public.cats c WHERE c.shelter_id=s.id AND c.stage='available'),'[]'::jsonb)) FROM public.shelters s WHERE s.slug=_slug $$;
REVOKE ALL ON FUNCTION public.public_adoption_page(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_adoption_page(text) TO anon,authenticated,service_role;
COMMENT ON TABLE public.settings IS 'DEPRECATED: replaced by shelter_settings for rescue isolation';
COMMENT ON TABLE public.user_roles IS 'DEPRECATED: rescue access is determined by shelter_members';